def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if len(alive_opponents) == 0:
        return float(min(budget, 18.0))

    prev_bids = []
    desperate_opp = False
    rich_aggressive = False
    for opp in alive_opponents:
        prev = opp.get('previous_trace') or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
            desperate_opp = True
        if opp.get('budget', 0) >= 180:
            rich_aggressive = True

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    low_supply = supply <= 17.0
    very_low_hp = hp <= 2 or no_water_days >= 1
    caution_hp = hp <= 4

    if very_low_hp:
        target = max(78.0, highest_prev + 6.0)
        if low_supply:
            target = max(target, 110.0)
        return float(min(budget, target))

    if low_supply:
        target = max(52.0, avg_prev * 0.55, highest_prev * 0.42)
        if desperate_opp:
            target = max(target, highest_prev + 2.0)
        if rich_aggressive and highest_prev >= 120.0:
            target = min(target, 88.0)
        if caution_hp:
            target = max(target, 72.0)
        return float(min(budget, target))

    target = 26.0
    if highest_prev > 0:
        if highest_prev >= 140.0:
            target = 24.0
        elif highest_prev >= 90.0:
            target = 30.0
        else:
            target = max(28.0, highest_prev * 0.38)

    if caution_hp:
        target = max(target, 48.0)
    if desperate_opp:
        target = max(target, 34.0)

    reserve_floor = DAILY_SALARY * 2.0
    if budget < reserve_floor:
        target = min(target, budget * 0.55)

    return float(min(budget, target))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    bid = DAILY_SALARY * 0.5 # Base bid

    if num_alive_opponents == 0:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    max_prev_bid = 0.0
    if yesterday_bids:
        max_prev_bid = max(yesterday_bids)

    # --- Bid Adjustments ---

    # 1. Critical HP / No Water Days: Survival is paramount
    if my_status['hp'] <= 2 or my_status['no_water_days'] > 0:
        bid = DAILY_SALARY * 1.1 # Bid very aggressively to secure water
    elif my_status['hp'] <= 5:
        bid = max(bid, DAILY_SALARY * 0.85) # High priority, but not critical yet

    # 2. React to Opponent Aggression (from yesterday's trace)
    if max_prev_bid > 0:
        if max_prev_bid >= DAILY_SALARY * 0.9: # Opponents are very aggressive
            if my_status['hp'] > 5: # If my HP is good, be competitive but not reckless
                bid = max(bid, DAILY_SALARY * 0.7)
            else: # If my HP is low, match or slightly exceed high bids
                bid = max(bid, max_prev_bid + 5)
        elif max_prev_bid >= DAILY_SALARY * 0.5: # Moderate opponent aggression
            bid = max(bid, max_prev_bid + 2) # Slightly exceed to win

    # 3. Adjust for Supply Scarcity
    total_water_needed_estimate = WATER_REQ * (num_alive_opponents + 1)

    if day_context['supply'] < total_water_needed_estimate:
        if my_status['hp'] > 5:
            bid = max(bid, DAILY_SALARY * 0.75)
        else:
            bid = max(bid, DAILY_SALARY * 0.95)
    elif day_context['supply'] >= total_water_needed_estimate + WATER_REQ * 2:
        if my_status['hp'] > 5 and my_status['budget'] > DAILY_SALARY * 5:
            bid = min(bid, DAILY_SALARY * 0.4)

    # 4. End-Game Pressure
    days_left = EPISODE_DAYS - day_context['day']
    if days_left <= 2:
        if my_status['hp'] < 10:
            bid = max(bid, DAILY_SALARY * 1.05)
        else:
            bid = max(bid, DAILY_SALARY * 0.6)
    elif days_left <= 4:
        if my_status['hp'] < 7:
            bid = max(bid, DAILY_SALARY * 0.9)

    # Final constraints
    bid = min(bid, my_status['budget'])
    bid = max(0.0, bid)

    if bid < DAILY_SALARY * 0.2 and my_status['hp'] < 10 and my_status['budget'] >= DAILY_SALARY * 0.2:
        bid = DAILY_SALARY * 0.2

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o.get('alive', False)]

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if not yesterday_bids:
        return min(my_status['budget'], DAILY_SALARY * 0.8)

    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids)
    max_prev_bid = max(yesterday_bids)

    if my_status['hp'] <= 3:
        return min(my_status['budget'], max_prev_bid * 1.1 + 5)

    if my_status['hp'] >= 8:
        return min(my_status['budget'], avg_prev_bid * 0.6)

    return min(my_status['budget'], avg_prev_bid * 0.95)
